from AlgorithmImports import *
from collections import deque


class ParallelTwoSlotStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=15)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        bars_present = {
            ticker: data.Bars.ContainsKey(symbol)
            for ticker, symbol in self.symbols.items()
        }

        if bars_present["SPY"]:
            self._update_spy(float(data.Bars[self.symbols["SPY"]].Close))

        if bars_present["AAPL"]:
            self._update_aapl(float(data.Bars[self.symbols["AAPL"]].Close))

        if not all(bars_present.values()):
            return

        spy_close = float(data.Bars[self.symbols["SPY"]].Close)
        aapl_close = float(data.Bars[self.symbols["AAPL"]].Close)

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and self._spy_crossed_below():
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi is not None and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and self._spy_crossed_above():
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) // spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_lot = quantity

        if (self.strategy_b_lot == 0 and
                self.aapl_rsi is not None and
                self.aapl_red_streak >= 3 and
                float(self.Portfolio.Cash) >= 20_000):
            quantity = int(20_000 // aapl_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.strategy_b_lot = quantity

    def _update_spy(self, close):
        current_sma = None
        if len(self.spy_closes) == 100:
            current_sma = (sum(self.spy_closes) - self.spy_closes[0] + close) / 100.0
        elif len(self.spy_closes) < 100:
            self.spy_closes.append(close)
            if len(self.spy_closes) == 100:
                current_sma = sum(self.spy_closes) / 100.0
            self.previous_spy_close = close
            self.previous_spy_sma = current_sma
            return

        self.spy_closes.append(close)
        self.previous_spy_close = close
        self.previous_spy_sma = current_sma

    def _update_aapl(self, close):
        if self.previous_aapl_close is not None:
            if close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = close - self.previous_aapl_close
            gain = max(change, 0.0)
            loss = max(-change, 0.0)

            if self.rsi_average_gain is None:
                self.rsi_seed_gains.append(gain)
                self.rsi_seed_losses.append(loss)
                if len(self.rsi_seed_gains) == 14:
                    self.rsi_average_gain = sum(self.rsi_seed_gains) / 14.0
                    self.rsi_average_loss = sum(self.rsi_seed_losses) / 14.0
                    self.aapl_rsi = self._calculate_rsi()
            else:
                self.rsi_average_gain = ((self.rsi_average_gain * 13) + gain) / 14.0
                self.rsi_average_loss = ((self.rsi_average_loss * 13) + loss) / 14.0
                self.aapl_rsi = self._calculate_rsi()

        self.aapl_closes.append(close)
        self.previous_aapl_close = close

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return 100.0
        rs = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + rs))

    def _spy_crossed_above(self):
        if len(self.spy_closes) < 101 or self.previous_spy_sma is None:
            return False
        current_sma = sum(self.spy_closes) / 100.0
        previous_close = self.spy_closes[-2]
        previous_sma = (sum(list(self.spy_closes)[:-1])) / 100.0
        return previous_close <= previous_sma and self.spy_closes[-1] > current_sma

    def _spy_crossed_below(self):
        if len(self.spy_closes) < 101 or self.previous_spy_sma is None:
            return False
        current_sma = sum(self.spy_closes) / 100.0
        previous_close = self.spy_closes[-2]
        previous_sma = (sum(list(self.spy_closes)[:-1])) / 100.0
        return previous_close >= previous_sma and self.spy_closes[-1] < current_sma
