                        else:
                            self.aapl_red_streak = 0
                    self.aapl_previous_close = close

        if len(present) != len(self.tickers):
            return

        if not self.spy_closes.is_ready or not self.aapl_rsi.is_ready:
            return

        spy_close = float(present["SPY"].close)
        aapl_close = float(present["AAPL"].close)

